(* spec 1RB1LD_1RC0RB_1LA1RC_1LC0LA *)
Definition r_AST_143_0000 : list (option Trans) := [t1RB;t1LD;t1RC;t0RB;t1LA;t1RC;t1LC;t0LA].
Lemma cv_AST_143_0000 : coversTr (row_to_tm r_AST_143_0000).
Proof. assert(Hprogress:forall x,exists y,Reach1 source_AST_143_0000(family_AST_143_0000 x)(family_AST_143_0000 y)).
  { intros[L R]. destruct(mn_return source_AST_143_0000 eq_refl eq_refl eq_refl eq_refl
      eq_refl eq_refl eq_refl eq_refl L R)as(U&V&H). exists(U,V);exact H. }
  assert(Hrec:forall N,exists j,N<=j /\ FiresAt(row_to_tm r_AST_143_0000)(StC,S1)j).
  { apply(conjugate_marked_return_fire source_AST_143_0000 _ perm_AST_143_0000 false
      _ family_AST_143_0000 (StC,S1) 7 ([S1],[S1])).
    - intros[] [];reflexivity.
    - rewrite <-lift_c0. apply csteps_lift. vm_compute;reflexivity.
    - exact Hprogress.
    - intros[L R];apply fires_here;reflexivity. }
  assert(Hcross:forall N,exists j,N<=j /\ FiresAt(row_to_tm r_AST_143_0000)(StD,S1)j).
  { apply(conjugate_marked_return_fire source_AST_143_0000 _ perm_AST_143_0000 false
      _ family_AST_143_0000 (StD,S1) 7 ([S1],[S1])).
    - intros[] [];reflexivity.
    - rewrite <-lift_c0. apply csteps_lift. vm_compute;reflexivity.
    - exact Hprogress.
    - intros[L R];apply mn_D1;reflexivity. }
  apply coversTr_nqh,neverqhtr_mirror.
  apply(ngram_check_neverqh_fuelmixtr_except_sound _ 3 0 2584 19
    skip_AST_143_0000 cert_AST_143_0000).
  - intros[[] []] H N;try discriminate.
    all:first[destruct(Hrec N)as(j&Hj&Hf);exists j;split;[exact Hj|apply mirror_fires;exact Hf]
             |destruct(Hcross N)as(j&Hj&Hf);exists j;split;[exact Hj|apply mirror_fires;exact Hf]].
